.impactsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2238;
    background: linear-gradient(160deg, #f4f2ec 0%, #ece9f0 100%);
    border-radius: 18px;
}

.impactsim-container * {
    box-sizing: border-box;
}

.impactsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1a1d3a 0%, #2b2f63 55%, #3c3f7a 100%);
    color: #f6f4fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(26, 29, 58, 0.30);
    border-bottom: 4px solid #c9a23f;
}

.impactsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.impactsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7cf8e;
    background: rgba(201, 162, 63, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.impactsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ddd9ee;
}

.impactsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2b2f63;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.impactsim-period-counter #currentDay,
.impactsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1a1d3a;
}

.impactsim-round-name {
    background: #e2def0;
    color: #2b2f63;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.impactsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f6ead0;
    padding: 4px 12px;
    border-radius: 999px;
}

.impactsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.impactsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2dded;
    box-shadow: 0 4px 14px rgba(26, 29, 58, 0.06);
    border-top: 4px solid #3c3f7a;
}

.impactsim-card-impact { border-top-color: #1f7a5a; }
.impactsim-card-win { border-top-color: #2f5fb0; }
.impactsim-card-margin { border-top-color: #c9a23f; }
.impactsim-card-cost { border-top-color: #6a4fb0; }

.impactsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b6880;
}

.impactsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1a1d3a;
}

.impactsim-card-impact .impactsim-value { color: #1f7a5a; }
.impactsim-card-win .impactsim-value { color: #2f5fb0; }
.impactsim-card-margin .impactsim-value { color: #a9831f; }
.impactsim-card-cost .impactsim-value { color: #6a4fb0; }

.impactsim-sublabel {
    font-size: 0.76rem;
    color: #847f97;
    line-height: 1.35;
}

.impactsim-margin-fail .impactsim-value { color: #c0392b; }
.impactsim-margin-target .impactsim-value { color: #1f7a5a; }

.impactsim-cost-over { border-top-color: #c0392b; }
.impactsim-cost-over .impactsim-value { color: #c0392b; }

.impactsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1a1d3a;
    color: #efecf8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.impactsim-budget-bar #budgetDisplay {
    font-size: 1.0rem;
    letter-spacing: 0.3px;
    color: #e7cf8e;
}

.impactsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a23f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(26, 29, 58, 0.05);
}

.impactsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.impactsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1a1d3a;
    margin-bottom: 6px;
}

.impactsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #36344a;
}

.impactsim-briefing-text strong { color: #1f7a5a; }
.impactsim-briefing-text em { color: #8a5a12; font-style: italic; }

.impactsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2dded;
    box-shadow: 0 4px 14px rgba(26, 29, 58, 0.06);
}

.impactsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1a1d3a;
    border-bottom: 2px solid #ece9f0;
    padding-bottom: 8px;
}

.impactsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a2d44;
    margin: 14px 0 6px;
}

.impactsim-container select,
.impactsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc6dc;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf9fc;
    color: #1b2238;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.impactsim-container select:focus,
.impactsim-container input[type="number"]:focus {
    outline: none;
    border-color: #3c3f7a;
    box-shadow: 0 0 0 3px rgba(60, 63, 122, 0.15);
}

.impactsim-container select option {
    background-color: #ffffff;
    color: #1b2238;
}

.impactsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #3c3f7a;
}

.impactsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2b2f63;
    margin-top: 4px;
}

.impactsim-range-readout span:last-child {
    color: #1f7a5a;
    font-weight: 800;
}

.impactsim-hint {
    font-size: 0.8rem;
    color: #847f97;
    margin-top: 4px;
    line-height: 1.4;
}

.impactsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.impactsim-container .btn-primary {
    background: linear-gradient(135deg, #2b2f63 0%, #3c3f7a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(43, 47, 99, 0.28);
}

.impactsim-container .btn-primary:hover {
    filter: brightness(1.10);
}

.impactsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdc6dc;
    color: #6b6880;
}

.impactsim-coach {
    background: #1a1d3a;
    color: #efecf8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(26, 29, 58, 0.22);
    border-left: 5px solid #c9a23f;
}

.impactsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7cf8e;
    margin-bottom: 8px;
}

.impactsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.impactsim-coach-body strong { color: #f0d68f; }
.impactsim-coach-body em { color: #bfc2ef; font-style: italic; }

.impactsim-history,
.impactsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2dded;
    box-shadow: 0 4px 14px rgba(26, 29, 58, 0.06);
}

.impactsim-history h3,
.impactsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1a1d3a;
}

.impactsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a2d44;
}

.impactsim-container table#usfHistoryTable th {
    background: #ece9f0;
    color: #1a1d3a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd7e8;
}

.impactsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0edf5;
}

.impactsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf9fc;
}

.impactsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .impactsim-container {
        padding: 14px;
    }
    .impactsim-header h1 {
        font-size: 1.7rem;
    }
    .impactsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .impactsim-value {
        font-size: 2rem;
    }
    .impactsim-clock {
        margin-left: 0;
    }
    .impactsim-period-counter {
        font-size: 0.88rem;
    }
    .impactsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .impactsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .im-cm-*) ── */
.im-cm { margin-top: 8px; }
.im-cm-incomplete { text-align: center; color: #6b6880; font-size: 1rem; padding: 18px; }
.im-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.im-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #1a1d3a 0%, #2b2f63 55%, #3c3f7a 100%); color: #f6f4fb; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(26, 29, 58, 0.30); }
.im-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.im-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.82; }
.im-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #e7cf8e; }
.im-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #dcd8ec; border-left: 5px solid #2b2f63; border-radius: 14px; padding: 16px 20px; }
.im-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b6880; }
.im-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #1a1d3a; line-height: 1.15; }
.im-cm-section { margin-bottom: 16px; }
.im-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #2b2f63; margin-bottom: 8px; }
.im-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.im-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.im-cm-ok { background: #dceee4; color: #14603f; border-color: #b3ddc6; }
.im-cm-no { background: #f6ddd9; color: #99331f; border-color: #e6b6aa; }
.im-cm-ico { font-weight: 800; }
.im-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.im-cm-kpi { background: #ffffff; border: 1px solid #dcd8ec; border-top: 4px solid #3c3f7a; border-radius: 12px; padding: 14px 12px; text-align: center; }
.im-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #1a1d3a; line-height: 1; }
.im-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #2b2f63; }
.im-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #8a86a0; }
.im-cm-insights { margin: 0; padding-left: 18px; color: #1b2238; }
.im-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .im-cm-head { flex-direction: column; } .im-cm-score { min-width: 0; } }

