(function() {
    'use strict';

    class ImpactAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Impact by Design`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (GBP, £k for money).
            this.START_IMPACT = 12;       // measurable-impact score, room to climb
            this.START_WIN = 20;          // four bidders, weak default position
            this.TARGET_MARGIN = 34;      // division target contribution margin %
            this.BUDGET_CAP = 1600;       // £1.6M envelope, in £k
            this.PRICE_FLOOR = 800;       // pricing input floor
            this.IMPACT_TARGET = 65;      // a credible, evidenced impact design
            this.WIN_TARGET = 60;         // odds you genuinely beat the field

            // Per-model total delivery cost (£k) for 240 managers / two cohorts.
            this.MODEL_COST = { blended: 780, hybrid: 920, embedded: 1120, residential: 1050 };
            // Measurement-design cost (£k).
            this.MEAS_COST = { baselinecontrol: 130, baseline: 70, endsurvey: 15, none: 0 };
            // Capacity / staffing cost (£k).
            this.CAP_COST = { hire: 110, reprioritise: 45, stretch: 0, noplan: 0 };

            // Concept truths.
            this.TRUE_OUTCOME = `business`;
            this.TRUE_LEVEL = `results`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    impact: this.START_IMPACT,
                    winProb: this.START_WIN,
                    margin: this.TARGET_MARGIN,
                    costUsed: 0,
                    price: 0,
                    marginThin: false,
                    capacityRisk: false,
                    bidLost: false,
                    impactHistory: [this.START_IMPACT],
                    winHistory: [this.START_WIN],
                    marginHistory: [this.TARGET_MARGIN],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            // Seeded defaults: a MIDDLING, neutral mix — not the textbook-correct play.
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    outcome: `learning`,
                    level: `behaviour`,
                    rigour: 50,
                    design: `modular`,
                    measurement: `baseline`,
                    alignment: 50,
                    model: `residential`,
                    capacity: `stretch`,
                    faculty: 40,
                    price: 1450,
                    kpi: `business`,
                    defend: `prestige`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const out = document.getElementById(`outcomeInput`);
                const lvl = document.getElementById(`levelInput`);
                const rig = document.getElementById(`rigourInput`);
                if (out) decisions.outcome = out.value;
                if (lvl) decisions.level = lvl.value;
                if (rig) decisions.rigour = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const des = document.getElementById(`designInput`);
                const mea = document.getElementById(`measurementInput`);
                const al = document.getElementById(`alignmentInput`);
                if (des) decisions.design = des.value;
                if (mea) decisions.measurement = mea.value;
                if (al) decisions.alignment = parseInt(al.value, 10);
                if (!Number.isFinite(decisions.alignment) || decisions.alignment < 0 || decisions.alignment > 100) {
                    warn(`warn_alignment_range`); return false;
                }
            } else if (round === 3) {
                const mo = document.getElementById(`modelInput`);
                const cap = document.getElementById(`capacityInput`);
                const fac = document.getElementById(`facultyInput`);
                if (mo) decisions.model = mo.value;
                if (cap) decisions.capacity = cap.value;
                if (fac) decisions.faculty = parseInt(fac.value, 10);
                if (!Number.isFinite(decisions.faculty) || decisions.faculty < 0 || decisions.faculty > 100) {
                    warn(`warn_faculty_range`); return false;
                }
            } else if (round === 4) {
                const pr = document.getElementById(`priceInput`);
                const kp = document.getElementById(`kpiInput`);
                const de = document.getElementById(`defendInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pr) decisions.price = parseFloat(pr.value);
                if (kp) decisions.kpi = kp.value;
                if (de) decisions.defend = de.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price < this.PRICE_FLOOR || decisions.price > this.BUDGET_CAP) {
                    warn(`warn_price_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let impactDelta = 0, winDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: restate the brief as a MEASURABLE business outcome (Common Error 1).
                switch (d.outcome) {
                    case `business`: impactDelta += 11; winDelta += 7; coachKey = `coach_r1_business`; break;
                    case `learning`: impactDelta += 3; winDelta += 1; coachKey = `coach_r1_learning`; break;
                    case `satisfaction`: impactDelta -= 9; winDelta -= 6; coachKey = `coach_r1_satisfaction`; break;
                    case `product`: impactDelta -= 7; winDelta -= 7; coachKey = `coach_r1_product`; break;
                }

                // Kirkpatrick: proof at L4 (results) is what Pennine demands; L3 is strong; L1/L2 fail it.
                switch (d.level) {
                    case `results`: impactDelta += 8; winDelta += 5; if (d.outcome === this.TRUE_OUTCOME) coachKey = `coach_r1_sharp`; break;
                    case `behaviour`: impactDelta += 5; winDelta += 2; break;
                    case `learning2`: impactDelta -= 4; coachKey = `coach_r1_level2`; break;
                    case `reaction`: impactDelta -= 9; winDelta -= 6; coachKey = `coach_r1_reaction`; break;
                }

                // Commitment to design for impact rather than applause.
                if (d.rigour >= 60) { impactDelta += 6; winDelta += 3; }
                else if (d.rigour <= 25) { impactDelta -= 7; winDelta -= 4; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.outcome === this.TRUE_OUTCOME && (d.level === `results` || d.level === `behaviour`)) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Align: design backward from the outcome + build measurement in (Jonsson).
                switch (d.design) {
                    case `backward`: impactDelta += 10; winDelta += 6; coachKey = `coach_r2_backward`; break;
                    case `modular`: impactDelta += 3; winDelta += 1; coachKey = `coach_r2_modular`; break;
                    case `flagship`: impactDelta -= 8; winDelta -= 3; coachKey = `coach_r2_flagship`; break;
                    case `catalogue`: impactDelta -= 10; winDelta -= 6; coachKey = `coach_r2_catalogue`; break;
                }

                // Measurement design: baseline + comparison + follow-through gives defensible attribution.
                switch (d.measurement) {
                    case `baselinecontrol`: impactDelta += 9; winDelta += 6; coachKey = (d.design === `backward`) ? `coach_r2_aligned` : coachKey; break;
                    case `baseline`: impactDelta += 5; winDelta += 2; break;
                    case `endsurvey`: impactDelta -= 8; winDelta -= 5; coachKey = `coach_r2_endsurvey`; break;
                    case `none`: impactDelta -= 12; winDelta -= 8; coachKey = `coach_r2_nomeasure`; break;
                }

                // Module-to-metric alignment.
                if (d.alignment >= 60) { impactDelta += 6; winDelta += 3; }
                else if (d.alignment <= 25) { impactDelta -= 6; coachKey = `coach_r2_lowalign`; }

                summaryKey = (d.design === `backward` && (d.measurement === `baselinecontrol` || d.measurement === `baseline`)) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Choose: delivery model & capacity (Common Errors 3 & 4).
                // Transfer-of-learning vs margin/prestige. Residential = margin-driven, weak transfer.
                switch (d.model) {
                    case `blended`: impactDelta += 8; winDelta += 6; coachKey = `coach_r3_blended`; break;
                    case `hybrid`: impactDelta += 10; winDelta += 7; coachKey = `coach_r3_hybrid`; break;
                    case `embedded`: impactDelta += 8; winDelta += 5; coachKey = `coach_r3_embedded`; break;
                    case `residential`: impactDelta -= 9; winDelta -= 5; coachKey = `coach_r3_residential`; break;
                }

                // Capacity: a high-touch model with no staffing plan is the classic blindness error.
                const highTouch = (d.model === `embedded` || d.model === `hybrid`);
                switch (d.capacity) {
                    case `hire`: impactDelta += 5; winDelta += 4; coachKey = (highTouch && d.model !== `residential`) ? `coach_r3_capacityplan` : coachKey; break;
                    case `reprioritise`: impactDelta += 4; winDelta += 2; break;
                    case `stretch`:
                        if (highTouch) { impactDelta -= 13; winDelta -= 8; ds.capacityRisk = true; coachKey = `coach_r3_stretch_hightouch`; }
                        else { impactDelta -= 6; winDelta -= 4; coachKey = `coach_r3_stretch`; }
                        break;
                    case `noplan`:
                        if (highTouch) { impactDelta -= 15; winDelta -= 9; ds.capacityRisk = true; coachKey = `coach_r3_noplan_hightouch`; }
                        else { impactDelta -= 8; winDelta -= 5; coachKey = `coach_r3_noplan`; }
                        break;
                }

                // Faculty mix: external practitioners + coaching lift transfer (unless model is residential).
                if (d.faculty >= 55) { impactDelta += 5; winDelta += 3; }
                else if (d.faculty <= 20) { impactDelta -= 5; coachKey = `coach_r3_internalonly`; }

                summaryKey = ((d.model === `blended` || d.model === `hybrid` || d.model === `embedded`) && (d.capacity === `hire` || d.capacity === `reprioritise`)) ? `sum_r3_good`
                    : (ds.capacityRisk ? `sum_r3_capacity` : (d.model === `residential` ? `sum_r3_margin` : `sum_r3_weak`));
            } else if (round === 4) {
                // Price & defend: the price-margin-impact triangle within a fixed budget (Common Error 5).
                // Total delivery cost from the model/measurement/capacity already chosen.
                const modelCost = this.MODEL_COST[d.model] || this.MODEL_COST.residential;
                const measCost = this.MEAS_COST[d.measurement] || 0;
                const capCost = this.CAP_COST[d.capacity] || 0;
                const facultyCost = Math.round((d.faculty / 100) * 90); // 0–90 £k
                const totalCost = modelCost + measCost + capCost + facultyCost;
                ds.costUsed = Math.min(this.BUDGET_CAP, totalCost);

                // Discount posture overrides the entered fee to a below-margin price.
                let price = d.price;
                if (d.defend === `discount`) price = Math.min(price, 1250);
                ds.price = price;

                // Contribution margin from price vs cost.
                const margin = price > 0 ? Math.round(((price - totalCost) / price) * 100) : 0;
                ds.margin = margin;
                if (margin < 18) ds.marginThin = true;

                // KPI commitment: hard + attributable wins; vague/satisfaction fail the brief.
                switch (d.kpi) {
                    case `attributable`: impactDelta += 11; winDelta += 8; coachKey = `coach_r4_attributable`; break;
                    case `business`: impactDelta += 4; winDelta += 2; coachKey = `coach_r4_business`; break;
                    case `vague`: impactDelta -= 11; winDelta -= 9; coachKey = `coach_r4_vague`; break;
                    case `satisfaction`: impactDelta -= 13; winDelta -= 10; coachKey = `coach_r4_satisfaction`; break;
                }

                // Defence posture and the win-vs-margin tension.
                switch (d.defend) {
                    case `value`: winDelta += 8; impactDelta += 4; coachKey = (d.kpi === `attributable`) ? `coach_r4_value` : coachKey; break;
                    case `prestige`: winDelta -= 2; coachKey = `coach_r4_prestige`; break;
                    case `discount`: winDelta += 3; coachKey = `coach_r4_discount`; break;
                    case `walk`: winDelta -= 9; coachKey = `coach_r4_walk`; break;
                }

                // Margin effects on win and the business case. Pricing below the margin line
                // buys the logo at a loss; protecting target margin strengthens the pitch.
                if (margin >= this.TARGET_MARGIN) { winDelta += 4; }
                else if (margin >= 25) { winDelta += 1; }
                else if (margin < 12) { winDelta -= 6; impactDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r4_loss`; }

                // A keen value price (not a fire-sale) is competitive against the consultancy.
                if (price <= 1450 && margin >= 25 && d.defend !== `discount`) winDelta += 4;
                if (price >= 1580) winDelta -= 4;

                // Conviction nudges win probability.
                winDelta += Math.round((d.conviction - 55) / 8);

                summaryKey = (d.kpi === `attributable` && d.defend === `value` && margin >= 25) ? `sum_r4_good`
                    : (margin < 12 || d.defend === `discount` ? `sum_r4_loss` : `sum_r4_weak`);
            }

            // Apply deltas with floors/ceilings; KPIs start low so wrong levers register all the way through.
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));
            ds.winProb = Math.max(0, Math.min(100, ds.winProb + winDelta));

            // Margin sits at target until round 4 prices it; record it each round for the chart.
            ds.marginHistory.push(Math.round(ds.margin));
            ds.impactHistory.push(Math.round(ds.impact));
            ds.winHistory.push(Math.round(ds.winProb));

            // Final-round verdict on whether the bid is won.
            if (round === this.ROUNDS.length) {
                if (ds.winProb < 45) ds.bidLost = true;
            }

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                winProb: Math.round(ds.winProb),
                winDelta: Math.round(winDelta),
                margin: Math.round(ds.margin),
                costUsed: Math.round(ds.costUsed),
                marginThin: ds.marginThin,
                capacityRisk: ds.capacityRisk,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

