        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const impact = Math.round(ds.impact);
            const winProb = Math.round(ds.winProb);
            const margin = Math.round(ds.margin);
            return Math.round(impact * 0.40 + winProb * 0.35 + Math.max(0, Math.min(100, (margin / this.TARGET_MARGIN) * 70 + 15)) * 0.25);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const impact = Math.round(ds.impact);
            const winProb = Math.round(ds.winProb);
            const margin = Math.round(ds.margin);

            const won = winProb >= 50 && !ds.bidLost;
            const impactful = impact >= this.IMPACT_TARGET;
            const marginOk = margin >= 25;
            const composite = this._composite(ds);

            let tierKey = `grade_lost`;
            if (won && impactful && marginOk && composite >= 72) tierKey = `grade_flagship`;
            else if (won && impactful) tierKey = `grade_impactled`;
            else if (won && !marginOk) tierKey = `grade_thinmargin`;
            else if (won) tierKey = `grade_shallow`;
            else if (winProb >= this.START_WIN + 18) tierKey = `grade_competitive`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (won && impactful && marginOk) insights.push(window.mySimulation.t(`insight_flagship`));
            else if (won && !marginOk) insights.push(window.mySimulation.t(`insight_thinmargin`));
            else if (won) insights.push(window.mySimulation.t(`insight_wonshallow`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (ds.marginThin) insights.push(window.mySimulation.t(`insight_loss`));
            if (ds.capacityRisk) insights.push(window.mySimulation.t(`insight_capacity`));
            if (impact < 45) insights.push(window.mySimulation.t(`insight_lowimpact`));
            if (won && impactful && margin >= this.TARGET_MARGIN) insights.push(window.mySimulation.t(`insight_protected`));

            return {
                impact: impact,
                winProb: winProb,
                margin: margin,
                won: won,
                impactful: impactful,
                marginOk: marginOk,
                capacityOk: !ds.capacityRisk,
                costUsed: ds.costUsed,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="im-cm"><p class="im-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="im-cm-chip ` + (ok ? `im-cm-ok` : `im-cm-no`) + `">` +
                `<span class="im-cm-ico">` + (ok ? `✓` : `✕`) + `</span>` + label + ` · ` +
