            const kpi = (label, val, sub) => `<div class="im-cm-kpi"><div class="im-cm-kpi-val">` + val +
                `</div><div class="im-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="im-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="im-cm">` +
  `<div class="im-cm-head">` +
    `<div class="im-cm-score"><div class="im-cm-score-num">` + Math.round(s.composite) +
       `<span class="im-cm-score-den">/100</span></div>` +
       `<div class="im-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="im-cm-verdict"><div class="im-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="im-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="im-cm-section"><div class="im-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="im-cm-chips">` + chip(!!s.won, t(`cm_t_won`)) + chip(!!s.impactful, t(`cm_t_impact`)) +
      chip(!!s.marginOk, t(`cm_t_margin`)) + chip(!!s.capacityOk, t(`cm_t_capacity`)) + `</div></div>` +
  `<div class="im-cm-section"><div class="im-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="im-cm-kpis">` +
      kpi(t(`cm_k_impact`), Math.round(s.impact), t(`cm_sub_impact`)) +
