      kpi(t(`cm_k_cost`), `£` + Math.round(Number(s.costUsed || 0)) + `k`, t(`cm_sub_cost`)) +
    `</div></div>` +
  (insights ? `<div class="im-cm-section"><div class="im-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="im-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
